import sys

MOD = 998244353


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]

    # bound[l][x]: smallest right endpoint of a condition at x
    # whose left endpoint is at least l.
    bound = [[n] * n for _ in range(n)]
    for t in range(2, len(data), 3):
        l, r, x = data[t] - 1, data[t + 1] - 1, data[t + 2] - 1
        if r < bound[l][x]:
            bound[l][x] = r
    for l in range(n - 2, -1, -1):
        a, b = bound[l], bound[l + 1]
        for k in range(n):
            if b[k] < a[k]:
                a[k] = b[k]

    inv = [0] * (n + 1)
    inv[1] = 1
    for i in range(2, n + 1):
        inv[i] = MOD - (MOD // i) * inv[MOD % i] % MOD

    # dp[l][r] is the valid count divided by (r-l+1)!.
    dp = [[0] * n for _ in range(n + 1)]
    for l in range(n, -1, -1):
        dp[l][l - 1] = 1

    for l in range(n - 1, -1, -1):
        row = dp[l]
        limits = bound[l]
        for r in range(l, n):
            total = 0
            for k in range(l, r + 1):
                if r < limits[k]:
                    total += row[k - 1] * dp[k + 1][r]
            row[r] = total % MOD * inv[r - l + 1] % MOD

    answer = dp[0][n - 1]
    for i in range(2, n + 1):
        answer = answer * i % MOD
    print(answer)


if __name__ == '__main__':
    solve()

