import sys
from collections import deque

MOD = 998244353


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    a = [x - 1 for x in data[2:]]
    deg = [0] * n
    for v in a:
        deg[v] += 1
    q = deque(i for i in range(n) if deg[i] == 0)
    # None represents a vector whose entries are all one.
    dp = [None] * n
    while q:
        v = q.popleft()
        p = a[v]
        cur = dp[v]
        par = dp[p]
        if cur is None:
            if par is None:
                dp[p] = list(range(1, m + 1))
            else:
                for j in range(m):
                    par[j] = par[j] * (j + 1) % MOD
        else:
            s = 0
            if par is None:
                for j in range(m):
                    s = (s + cur[j]) % MOD
                    cur[j] = s
                dp[p] = cur
            else:
                for j in range(m):
                    s = (s + cur[j]) % MOD
                    par[j] = par[j] * s % MOD
        dp[v] = None
        deg[p] -= 1
        if deg[p] == 0:
            q.append(p)

    answer = 1
    for start in range(n):
        if deg[start] == 0:
            continue
        v = start
        acc = None
        # All vertices of a directed cycle must have the same value.
        while deg[v]:
            deg[v] = 0
            cur = dp[v]
            if cur is not None:
                if acc is None:
                    acc = cur
                else:
                    for j in range(m):
                        acc[j] = acc[j] * cur[j] % MOD
            dp[v] = None
            v = a[v]
        ways = m if acc is None else sum(acc) % MOD
        answer = answer * ways % MOD
    print(answer)


if __name__ == '__main__':
    solve()

