import sys
from math import gcd

MOD = 998244353


def solve(n, a):
    factors = {}
    for i, x in enumerate(a):
        p = 2
        while p * p <= x:
            if x % p == 0:
                e = 0
                while x % p == 0:
                    x //= p
                    e += 1
                if p not in factors:
                    factors[p] = [0] * (n - 1)
                factors[p][i] = e
            p += 1
        if x > 1:
            if x not in factors:
                factors[x] = [0] * (n - 1)
            factors[x][i] = 1

    ans = 1
    for p, es in factors.items():
        g = 0
        for e in es:
            g = gcd(g, e)
        if g > 1:
            p = pow(p, g, MOD)
            es = [e // g for e in es]

        powers = [1] * (sum(es) + 1)
        for h in range(1, len(powers)):
            powers[h] = powers[h - 1] * p % MOD

        # Prefixes are normalized so their minimum exponent is zero.
        # dp[h] sums their weights with final exponent h.
        dp = [1]
        for i, e in enumerate(es, 1):
            if e == 0:
                dp = [v * powers[h] % MOD for h, v in enumerate(dp)]
                continue

            # Increase the final exponent by e.
            ndp = [0] * e + [
                v * powers[h + e] % MOD for h, v in enumerate(dp)
            ]
            # Decrease without introducing a new minimum.
            for h in range(e, len(dp)):
                ndp[h - e] = (ndp[h - e] + dp[h] * powers[h - e]) % MOD
            # A new minimum shifts all i previous exponents upward.
            for h in range(min(e, len(dp))):
                ndp[0] = (ndp[0] + dp[h] * pow(p, i * (e - h), MOD)) % MOD
            dp = ndp

        ans = ans * sum(dp) % MOD
    return ans


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    print(solve(data[0], data[1:]))


if __name__ == '__main__':
    main()

