import sys
import math
from operator import mul
from collections import Counter


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]
    mod = 998244353
    freq = Counter(a)
    limit = max(a)

    # With a small alphabet, a direct dot product runs mostly in C.
    if len(freq) <= 250:
        values = list(freq)
        index = {x: i for i, x in enumerate(values)}
        rows = {x: [math.gcd(x, y) for y in values] for x in values}
        weights = [0] * len(values)
        answer = 0
        power = 1
        out = []
        for x in a:
            contribution = sum(map(mul, rows[x], weights))
            k = index[x]
            weights[k] = (weights[k] + power) % mod
            answer = (2 * answer + contribution) % mod
            power = power * 2 % mod
            out.append(str(answer))
        sys.stdout.write('\n'.join(out))
        return

    phi = list(range(limit + 1))
    tau = [0] * (limit + 1)
    for d in range(1, limit + 1):
        for j in range(d, limit + 1, d):
            tau[j] += 1
    for p in range(2, limit + 1):
        if phi[p] == p:
            for j in range(p, limit + 1, p):
                phi[j] -= phi[j] // p

    order = sorted(freq, key=lambda x: freq[x] * tau[x], reverse=True)
    work = sum(freq[x] * tau[x] for x in order)
    light_count = n
    best = work * 150
    h = 0
    for k, x in enumerate(order[:180], 1):
        work -= freq[x] * tau[x]
        light_count -= freq[x]
        cost = work * 150 + n * k * 43 + light_count * k * 85
        if cost < best:
            best = cost
            h = k
    heavy = order[:h]
    heavy_index = {x: i for i, x in enumerate(heavy)}
    rows = {x: [math.gcd(x, y) for y in heavy] for x in freq} if h else {}
    divisors = [None] * (limit + 1)
    for x in freq:
        if x not in heavy_index:
            divisors[x] = []
    for d in range(1, limit + 1):
        f = phi[d]
        for x in range(d, limit + 1, d):
            if divisors[x] is not None:
                divisors[x].append((d, f))

    sums = [0] * (limit + 1)
    weights = [0] * h
    light_contribution = [0] * h
    answer = 0
    power = 1
    out = []
    for x in a:
        if h:
            row = rows[x]
            contribution = sum(map(mul, row, weights))
        else:
            contribution = 0
        k = heavy_index.get(x, -1)
        if k >= 0:
            contribution += light_contribution[k]
            weights[k] = (weights[k] + power) % mod
        else:
            for d, f in divisors[x]:
                old = sums[d]
                contribution += old * f
                z = old + power
                if z >= mod:
                    z -= mod
                sums[d] = z
            if h:
                for j, g in enumerate(row):
                    light_contribution[j] += power * g
        answer = (2 * answer + contribution) % mod
        power = power * 2 % mod
        out.append(str(answer))
    sys.stdout.write('\n'.join(out))


if __name__ == '__main__':
    solve()

