import sys
from functools import lru_cache


def solve(A, B, M):
    bits = (max(A, B) + 1).bit_length()
    mask = (1 << bits) - 1

    # Store the lengths of columns or rows, whichever is shorter.
    if A <= B:
        d = A
        limits = [B] * (A - 1) + [B - 1]
        columns = True
    else:
        d = B
        limits = [A] * (B - 1) + [A - 1]
        columns = False

    shifts = [bits * i for i in range(d)]
    steps = [1 << s for s in shifts]
    target = sum(v << s for v, s in zip(limits, shifts))

    @lru_cache(None)
    def dp(state):
        if state == target:
            return 1
        counts = [(state >> s) & mask for s in shifts]
        total = 0
        for i in range(d):
            v = counts[i]
            if v == limits[i] or (i and v >= counts[i - 1]):
                continue
            if columns:
                # Each entry of the final column must come after
                # the entry one row lower in the preceding column.
                if i == d - 1 and v + 1 >= counts[i - 1]:
                    continue
            elif v == A - 1 and i < d - 1 and counts[i + 1] < A - 1:
                continue
            total += dp(state + steps[i])
        return total % M

    good_tableaux = dp(0)

    # Hook-length formula for (A, ..., A, A-1).
    factorial = 1
    for i in range(1, A * B):
        factorial = factorial * i % M
    hooks = 1
    for i in range(B):
        for j in range(A - (i == B - 1)):
            right = A - (i == B - 1) - 1 - j
            below = B - 1 - i - (j == A - 1)
            hooks = hooks * (right + below + 1) % M

    return good_tableaux * factorial * pow(hooks, M - 2, M) % M


if __name__ == '__main__':
    print(solve(*map(int, sys.stdin.buffer.read().split())))

