import sys
from math import gcd


def solve(data):
    it = iter(map(int, data.split()))
    n = next(it)
    budget = next(it)
    processes = []
    for _ in range(n):
        a, p, b, q = next(it), next(it), next(it), next(it)
        # S has no greater cost per unit of capacity than T.
        if p * b > q * a:
            a, p, b, q = b, q, a, p
        # a/g T machines can be replaced by b/g S machines.
        options = [(j * b, j * q) for j in range(a // gcd(a, b))]
        processes.append((a, p, options))

    def feasible(w):
        total = 0
        for a, p, options in processes:
            best = ((w + a - 1) // a) * p
            for capacity, cost in options:
                if capacity >= w:
                    if cost < best:
                        best = cost
                    break
                cost += ((w - capacity + a - 1) // a) * p
                if cost < best:
                    best = cost
            total += best
            if total > budget:
                return False
        return True

    lo, hi = 0, budget * 100 + 1
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid
    return str(lo)


if __name__ == '__main__':
    print(solve(sys.stdin.buffer.read()))

