class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        mod = 10**9 + 7
        length = len(s)

        depth = [0] * (length + 1)
        for value in range(2, length + 1):
            depth[value] = 1 + depth[value.bit_count()]
        good = [value for value in range(1, length + 1) if depth[value] < k]

        fact = [1] * (length + 1)
        for i in range(1, length + 1):
            fact[i] = fact[i - 1] * i % mod
        inv = [1] * (length + 1)
        inv[length] = pow(fact[length], mod - 2, mod)
        for i in range(length, 0, -1):
            inv[i - 1] = inv[i] * i % mod

        answer = 0
        prefix = 0
        for i, bit in enumerate(s):
            if bit == '1':
                # Put zero here, then freely choose the remaining bits.
                remaining = length - i - 1
                subtotal = 0
                for weight in good:
                    ones = weight - prefix
                    if ones < 0:
                        continue
                    if ones > remaining:
                        break
                    subtotal += inv[ones] * inv[remaining - ones] % mod
                answer = (answer + fact[remaining] * subtotal) % mod
                prefix += 1
        return answer

