import sys

MOD = 998244353


def solve(n, m, k, x):
    changes = sum(x[i] != x[i - 1] for i in range(1, m))
    remaining = n - (m * k - 1 + changes)
    if remaining < 0:
        return 0

    dp = [1] + [0] * remaining
    for j in range(1, k):
        for _ in range(m):
            for s in range(1, remaining + 1):
                dp[s] = (dp[s] + j * dp[s - 1]) % MOD

    for _ in range(changes):
        for s in range(1, remaining + 1):
            dp[s] = (dp[s] + (k - 2) * dp[s - 1]) % MOD

    factorial = 1
    for j in range(1, k):
        factorial = factorial * j % MOD
    return dp[remaining] * pow(factorial, m, MOD) % MOD


