from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(2, n + 1):
            fact[i] = fact[i - 1] * i

        odd, even = (n + 1) // 2, n // 2
        total = fact[odd] * fact[even] * (2 if n % 2 == 0 else 1)
        if k > total:
            return []

        remaining = list(range(1, n + 1))
        result = []
        required = 1 if n % 2 else -1
        while remaining:
            for i, value in enumerate(remaining):
                parity = value % 2
                if required != -1 and parity != required:
                    continue
                ways = fact[odd - parity] * fact[even - (1 - parity)]
                if k > ways:
                    k -= ways
                else:
                    result.append(value)
                    remaining.pop(i)
                    odd -= parity
                    even -= 1 - parity
                    required = 1 - parity
                    break
        return result

