from bisect import bisect_right

def solve(n,a,b,c):
    down=[]; up=[]; common=[]
    for x,y,w in zip(a,b,c):
        if x != y:
            if x: down.append(w)
            else: up.append(w)
        elif x: common.append(w)
    down.sort(reverse=True)
    up.sort()
    s=sum(common)
    m=len(down)+len(up)
    cost=s*m+sum(i*w for i,w in enumerate(down))+sum((len(up)-i)*w for i,w in enumerate(up))
    ans=cost
    required=sorted(down+up)
    pref=[0]
    for w in required: pref.append(pref[-1]+w)
    common.sort(reverse=True)
    for w in common:
        j=bisect_right(required,w)
        cost+=2*s-(m+1)*w+pref[j]+(m-j)*w
        s-=w
        if cost<ans: ans=cost
    return ans

