from math import gcd

class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        powers = [1 % k] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        m = (n + 1) // 2
        weights = [
            (powers[i] + powers[n - 1 - i]) % k
            if i != n - 1 - i else powers[i]
            for i in range(m)
        ]

        # Suffix contributions can attain precisely the multiples of
        # this gcd modulo k: digits 0..9 cover every residue modulo k.
        suffix = [k] * (m + 1)
        for i in range(m - 1, -1, -1):
            suffix[i] = gcd(suffix[i + 1], weights[i])

        answer = []
        remainder = 0
        for i, w in enumerate(weights):
            for d in range(9, -1 if i else 0, -1):
                nxt = (remainder + d * w) % k
                if nxt % suffix[i + 1] == 0:
                    answer.append(str(d))
                    remainder = nxt
                    break

        half = ''.join(answer)
        return half + (half[:-1] if n % 2 else half)[::-1]

