import heapq, random, time
from functools import lru_cache

def prefix_scores(a):
    low = []
    high = []
    sl = sh = 0
    scores = [0]
    push = heapq.heappush
    poppush = heapq.heappushpop
    for i, x in enumerate(a):
        if i % 2 == 0:
            y = poppush(high, x)
            push(low, -y)
            sh += x - y
            sl += y
        else:
            y = -poppush(low, -x)
            push(high, y)
            sl += x - y
            sh += y
            scores.append(sh - sl)
    return scores

def solve(a):
    n = len(a)
    k = n // 2
    if n % 2 == 0:
        b = sorted(a)
        return sum(b[k:]) - sum(b[:k])
    p = prefix_scores(a[:-1])
    s = prefix_scores(a[:0:-1])
    return max(p[i] + s[k-i] for i in range(k+1))

@lru_cache(None)
def brute(a):
    if len(a)<2: return 0
    return max(abs(a[i]-a[i+1])+brute(a[:i]+a[i+2:]) for i in range(len(a)-1))
