import sys

MOD = 998244353


def solve_case(h, w, rows):
    n = h + w
    parent = list(range(n))
    size = [1] * n
    weight = [0] * n
    columns = bytearray(w)
    components = n

    def find(x):
        parity = 0
        while parent[x] != x:
            p = parent[x]
            weight[x] ^= weight[p]
            parent[x] = parent[p]
            parity ^= weight[x]
            x = parent[x]
        return x, parity

    valid = True
    for i, row in enumerate(rows):
        if not valid:
            continue
        horizontal = 0
        for j, ch in enumerate(row):
            if ch == 65:
                horizontal ^= 1
                columns[j] ^= 1
            else:
                a, pa = find(i)
                b, pb = find(h + j)
                d = horizontal ^ columns[j] ^ 1 ^ pa ^ pb
                if a == b:
                    if d:
                        valid = False
                        break
                else:
                    if size[a] < size[b]:
                        a, b = b, a
                    parent[b] = a
                    weight[b] = d
                    size[a] += size[b]
                    components -= 1
        if horizontal:
            valid = False

    if not valid or any(columns):
        return 0
    return pow(2, components, MOD)


def main():
    read = sys.stdin.buffer.readline
    t = int(read())
    out = []
    for _ in range(t):
        h, w = map(int, read().split())
        rows = (read().strip() for _ in range(h))
        out.append(str(solve_case(h, w, rows)))
    print('\n'.join(out))


if __name__ == '__main__':
    main()

