import sys


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[0], data[1]
    graph = [[] for _ in range(n)]
    for i in range(2, len(data), 3):
        x, y, z = data[i] - 1, data[i + 1] - 1, data[i + 2]
        graph[x].append((y, z))
        graph[y].append((x, z))
    del data

    values = [-1] * n
    for root in range(n):
        if values[root] != -1:
            continue
        values[root] = 0
        component = [root]
        mask = 0
        for u in component:
            for v, z in graph[u]:
                wanted = values[u] ^ z
                if values[v] == -1:
                    values[v] = wanted
                    mask |= wanted
                    component.append(v)
                elif values[v] != wanted:
                    print(-1)
                    return

        flip = 0
        size = len(component)
        for bit in range(mask.bit_length()):
            count = sum((values[v] >> bit) & 1 for v in component)
            if count * 2 > size:
                flip |= 1 << bit
        if flip:
            for v in component:
                values[v] ^= flip

    print(*values)


