import sys
from collections import deque


def solve(n, edges, s, t):
    g = [[] for _ in range(n)]
    for u, v in edges:
        g[u].append(v)
        g[v].append(u)

    def bfs(start):
        dist = [-1] * n
        dist[start] = 0
        q = deque([start])
        while q:
            u = q.popleft()
            for v in g[u]:
                if dist[v] < 0:
                    dist[v] = dist[u] + 1
                    q.append(v)
        return dist

    ds = bfs(s)
    dt = bfs(t)
    d = ds[t]

    path = [t]
    x = t
    while x != s:
        x = next(v for v in g[x] if ds[v] == ds[x] - 1)
        path.append(x)

    internal = set(path[1:-1])
    branch = any(len(g[v]) >= 3 for v in internal)
    inf = 10**18
    if branch:
        ans = 2 * d + 2
    else:
        h = min((min(ds[v], dt[v]) for v in range(n)
                 if len(g[v]) >= 3), default=inf)
        ans = 2 * d + 4 * h + 4

    path_edges = {(min(a, b), max(a, b))
                  for a, b in zip(path, path[1:])}

    # An alternative route of length d or d+1 improves the branch bound.
    for u, v in edges:
        if (u, v) not in path_edges:
            length = min(ds[u] + dt[v], ds[v] + dt[u]) + 1
            if length <= d + 1:
                ans = min(ans, d + length)

    # Without an internal branch, every alternative simple route avoids
    # all internal vertices of the chosen path.
    if not branch:
        dist = [-1] * n
        dist[s] = 0
        q = deque([s])
        while q:
            u = q.popleft()
            for v in g[u]:
                if v in internal or (min(u, v), max(u, v)) in path_edges:
                    continue
                if dist[v] < 0:
                    dist[v] = dist[u] + 1
                    q.append(v)
        if dist[t] >= 0:
            ans = min(ans, d + dist[t])

    return ans if ans < inf else -1


def main():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(it)
    m = next(it)
    s = next(it) - 1
    t = next(it) - 1
    edges = [(next(it) - 1, next(it) - 1) for _ in range(m)]
    print(solve(n, edges, s, t))


if __name__ == '__main__':
    main()

