from math import gcd, lcm
from itertools import product
from time import perf_counter
class Solution:
    def maxScore(self, nums: List[int]) -> int:
        n = len(nums)
        pg = [0] * (n + 1)
        pl = [1] * (n + 1)
        for i, x in enumerate(nums):
            pg[i + 1] = gcd(pg[i], x)
            pl[i + 1] = lcm(pl[i], x)
        best = pg[n] * pl[n]
        sg, sl = 0, 1
        for i in range(n - 1, -1, -1):
            best = max(best, gcd(pg[i], sg) * lcm(pl[i], sl))
            sg = gcd(sg, nums[i])
            sl = lcm(sl, nums[i])
        return best

def reference(a):
    best = 0
    for skip in range(-1, len(a)):
        b = [x for i,x in enumerate(a) if i != skip]
        if b:
            g = l = b[0]
            for x in b[1:]:
                g = gcd(g,x)
                l = l*x//gcd(l,x)
            best = max(best,g*l)
    return best
