import sys
from math import isqrt


def count(n):
    # Nine divisors means either p^8 or p^2*q^2 for distinct primes.
    m = isqrt(n)
    sieve = bytearray(b'\x01') * (m + 1)
    sieve[0] = 0
    if m >= 1:
        sieve[1] = 0
    for p in range(2, isqrt(m) + 1):
        if sieve[p]:
            start = p * p
            sieve[start:m + 1:p] = b'\x00' * ((m - start) // p + 1)
    primes = [p for p in range(2, m + 1) if sieve[p]]

    ans = 0
    j = len(primes) - 1
    for i, p in enumerate(primes):
        while j > i and p * primes[j] > m:
            j -= 1
        if j <= i:
            break
        ans += j - i

    for p in primes:
        if p ** 8 > n:
            break
        ans += 1
    return ans


