class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        mod = 10**9 + 7
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - 97] += 1

        # counts[start] represents 'a'; the alphabet rotates in place.
        start = 0
        for _ in range(t):
            start = (start - 1) % 26
            b = (start + 1) % 26
            counts[b] = (counts[b] + counts[start]) % mod

        return sum(counts) % mod

