from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        # z[i] is the common-prefix length of nums and nums[i:].
        z = [0] * n
        l = r = 0
        for i in range(1, n):
            if i < r:
                z[i] = min(r - i, z[i - l])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > r:
                l, r = i, i + z[i]

        ans = 0
        dp = [0] * (n + 1)
        for i in range(n - 2, 0, -1):
            first = z[i] >= i
            if first:
                ans += max(0, n - 2 * i)
            # Count the second condition only where the first was not counted.
            limit = min((n + i) // 2, 2 * i - 1) if first else (n + i) // 2
            x = nums[i]
            # Ascending order preserves the previous row's dp[j+1].
            for j in range(i + 1, n):
                if nums[j] == x:
                    v = dp[j + 1] + 1
                    dp[j] = v
                    if j <= limit and v >= j - i:
                        ans += 1
                else:
                    dp[j] = 0
        return ans

