from typing import List

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        # Each state gives the colors of the current mirrored pair.
        pairs = [(a, b) for a in range(3) for b in range(3) if a != b]
        transitions = [
            tuple(k for k, (x, y) in enumerate(pairs) if x != a and y != b)
            for a, b in pairs
        ]
        dp = [0] * 6
        for i in range(n // 2):
            left, right = cost[i], cost[n - 1 - i]
            dp = [
                left[a] + right[b] + min(dp[p], dp[q], dp[r])
                for (a, b), (p, q, r) in zip(pairs, transitions)
            ]
        return min(dp)

